for(const c of prior.comparisons){const s=c.owner_stages,con=c.latest_corrected_conclusions;comparisonsText+=`### ${c.id} ${c.title}

Recorded request: ${s.earliest_supported_request?.source_summary_anchor_date||'Not established for this stage'}. ${s.earliest_supported_request?.description||''}

`;if(con?.public_statement)comparisonsText+=con.public_statement+'

';if(con?.chronology_relation)comparisonsText+=con.chronology_relation+'

';if(con?.material_difference)comparisonsText+=con.material_difference+'

';comparisonsText+='Sources: '+c.industry_dates.map(d=>`[${d.title}](${d.url}) (${d.date||'date unresolved'})`).join('; ')+'. Full stages and corrections: [comparison data](prior-work/corrected-comparisons.json).

';}
